def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The most common color is the background.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the full row or column that acts as the divider.
    divider = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            divider = ("h", r, row[0])
            break
    if divider is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                divider = ("v", c, vals[0])
                break
    if divider is None:
        return out

    orient, line, divider_color = divider
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != divider_color]
    if not points:
        return out

    # Move the object until it is adjacent to the divider.
    if orient == "h":
        minr = min(r for r, c in points)
        maxr = max(r for r, c in points)
        if maxr < line:
            dr = line - 1 - maxr
            new_edge = minr + dr
            marker = new_edge - 1
        else:
            dr = line + 1 - minr
            new_edge = maxr + dr
            marker = new_edge + 1

        for r, c in points:
            out[r][c] = bg
        for r, c in points:
            nr = r + dr
            if 0 <= nr < h:
                out[nr][c] = grid[r][c]
        if 0 <= marker < h:
            out[marker] = [8] * w

    else:
        minc = min(c for r, c in points)
        maxc = max(c for r, c in points)
        if maxc < line:
            dc = line - 1 - maxc
            new_edge = minc + dc
            marker = new_edge - 1
        else:
            dc = line + 1 - minc
            new_edge = maxc + dc
            marker = new_edge + 1

        for r, c in points:
            out[r][c] = bg
        for r, c in points:
            nc = c + dc
            if 0 <= nc < w:
                out[r][nc] = grid[r][c]
        if 0 <= marker < w:
            for r in range(h):
                out[r][marker] = 8

    return out
